import { useEffect, useState } from 'react';

/** How often the clock is read. A quarter second keeps a whole-second display honest. */
const TICK_MS = 250;

/**
 * Whole seconds since `running` became true for this `runKey`, read from the
 * wall clock so a tab in the background does not slow the game down. It
 * holds its value when `running` turns false; a new `runKey` starts from
 * zero.
 */
export function useClock(running: boolean, runKey: unknown): number {
  const [tick, setTick] = useState<{ key: unknown; seconds: number }>({ key: runKey, seconds: 0 });

  useEffect(() => {
    if (!running) return undefined;
    const startedAt = Date.now();
    const id = window.setInterval(() => {
      setTick({ key: runKey, seconds: Math.floor((Date.now() - startedAt) / 1000) });
    }, TICK_MS);
    return () => {
      window.clearInterval(id);
    };
  }, [running, runKey]);

  return tick.key === runKey ? tick.seconds : 0;
}

/** Seconds as m:ss; the stylesheet sets tabular figures so it does not jump. */
export function formatClock(seconds: number): string {
  const whole = Math.max(0, Math.round(seconds));
  return `${String(Math.floor(whole / 60))}:${String(whole % 60).padStart(2, '0')}`;
}
