import { Suspense, lazy, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { MODES, PRO_MODES, type LanguageCode, type ModeId } from '@lexpad/core';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { Skeleton } from '@/components/ui/Skeleton.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { offerable, proHere, useBilling } from '@/features/billing/state.js';
import { shows } from '@/features/schedule/data.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { t } from '@/i18n/index.js';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { MODES_HOME } from './ModeScreen.js';
import { useCanListen } from './useCanListen.js';
import { MODES_LOADING, canFeed, fewWordsBody, loadModes, type ModesView } from './data.js';
import styles from './Modes.module.css';

/** What every mode screen is given. */
export interface ModeProps {
  view: ModesView;
  /** The notebook's target language: the words, the examples, the voice. */
  lang: LanguageCode;
  /** The notebook's meaning language. */
  meaningLang: LanguageCode;
}

/*
 * One chunk per mode, fetched when it is opened (spec 6.9), so the modes add
 * nothing to the first load or to the Decks screen beyond the picker.
 */
const SCREENS: Record<ModeId, React.LazyExoticComponent<(props: ModeProps) => React.JSX.Element>> = {
  match: lazy(() => import('./match/Match.js').then((m) => ({ default: m.Match }))),
  speed: lazy(() => import('./speed/Speed.js').then((m) => ({ default: m.Speed }))),
  dictation: lazy(() => import('./dictation/Dictation.js').then((m) => ({ default: m.Dictation }))),
  builder: lazy(() => import('./builder/Builder.js').then((m) => ({ default: m.Builder }))),
  collocation: lazy(() => import('./collocation/Collocation.js').then((m) => ({ default: m.Collocation }))),
  sayIt: lazy(() => import('./say/SayIt.js').then((m) => ({ default: m.SayIt }))),
  sentence: lazy(() => import('./sentence/UseInSentence.js').then((m) => ({ default: m.UseInSentence }))),
};

function modeOf(value: string | undefined): ModeId | undefined {
  return MODES.find((mode) => mode === value);
}

/**
 * /practice/:mode. Checks, in order, that the mode is switched on for this
 * account, that there is a notebook, that the notebook can feed it, that
 * the device can (a voice for Dictation, a microphone for Say it) and, for
 * the two Pro modes, that this notebook has Pro; then loads the mode.
 * Every refusal is an empty state in its own words.
 */
export function ModeRoute(): React.JSX.Element {
  const params = useParams();
  const mode = modeOf(params.mode);
  const now = useCurrentDay();
  const view = useLiveQuery(() => loadModes(now), MODES_LOADING, [now]);
  const lang = view.notebook?.targetLang ?? 'en';
  const meaningLang = view.notebook?.meaningLang ?? 'en';
  const canSpeak = useCanSpeak(lang);
  const canListen = useCanListen(mode === 'sayIt');
  const billing = useBilling((state) => state.state);
  const ensure = useBilling((state) => state.ensure);
  useEffect(() => {
    if (mode !== undefined && PRO_MODES.has(mode)) ensure();
  }, [ensure, mode]);

  if (!view.ready) {
    return (
      <Frame>
        <Skeleton lines={4} />
        <p className="sr-only" role="status">
          {t('modes.loading')}
        </p>
      </Frame>
    );
  }
  if (mode === undefined || !shows(view.srs, mode)) {
    return <Refusal icon="lock" title={t('modes.unavailable')} body={t('modes.unavailableBody')} />;
  }
  if (view.notebook === undefined) {
    return <Refusal icon="notebook" title={t('modes.noNotebook')} body={t('modes.noNotebookBody')} />;
  }
  if (!canFeed(mode, view.words, lang)) {
    const few = fewWordsBody(mode);
    return (
      <Refusal
        icon="notebook"
        title={t('modes.fewTitle')}
        body={t(few.key as 'modes.fewMatch', few.values)}
      />
    );
  }
  const language = LANGUAGE_NAMES[lang];
  if (mode === 'dictation' && !canSpeak) {
    return (
      <Refusal
        icon="speaker"
        title={t('modes.noVoiceTitle', { language })}
        body={t('modes.noVoice', { language })}
      />
    );
  }
  if (mode === 'sayIt' && canListen === false) {
    return <Refusal icon="mic" title={t('modes.noMicTitle')} body={t('modes.noMic', { language })} />;
  }
  if (mode === 'sayIt' && canListen === undefined) return <Frame />;
  if ((mode === 'sayIt' || mode === 'sentence') && !proHere(billing, lang, meaningLang)) {
    return (
      <Locked
        mode={mode}
        about={{ targetLang: lang, meaningLang }}
        canOffer={offerable(billing, lang, meaningLang)}
      />
    );
  }

  const Screen = SCREENS[mode];
  return (
    <Suspense fallback={<Frame />}>
      <Screen view={view} lang={lang} meaningLang={meaningLang} />
    </Suspense>
  );
}

/** The frame while a mode's code or data is on its way: nothing drawn for the first moment. */
function Frame({ children }: { children?: React.ReactNode }): React.JSX.Element {
  return <main className={styles.screen}>{children}</main>;
}

function Refusal({
  icon,
  title,
  body,
}: {
  icon: 'lock' | 'notebook' | 'speaker' | 'mic';
  title: string;
  body: string;
}): React.JSX.Element {
  const navigate = useNavigate();
  return (
    <Frame>
      <EmptyState
        middle
        icon={icon}
        tone="quiet"
        title={title}
        body={body}
        actions={
          <button
            type="button"
            className={styles.secondary}
            onClick={() => {
              void navigate(MODES_HOME);
            }}
          >
            {t('modes.backToDecks')}
          </button>
        }
      />
    </Frame>
  );
}

/**
 * A Pro mode on a plan without it. The offer is the one component that may
 * mention Pro (`ProOffer`), here without a price; where it has nothing to
 * offer (selling switched off), a plain line says what the mode is part of.
 */
function Locked({
  mode,
  about,
  canOffer,
}: {
  mode: 'sayIt' | 'sentence';
  about: { targetLang: string; meaningLang: string };
  canOffer: boolean;
}): React.JSX.Element {
  const navigate = useNavigate();
  return (
    <Frame>
      <EmptyState
        middle
        icon="lock"
        tone="quiet"
        title={t('modes.lockedTitle')}
        body={mode === 'sayIt' ? t('modes.lockedSayIt') : t('modes.lockedSentence')}
        actions={
          <>
            {canOffer && <ProOffer occasion={mode} about={about} showPrice={false} />}
            <button
              type="button"
              className={styles.secondary}
              onClick={() => {
                void navigate(MODES_HOME);
              }}
            >
              {t('modes.backToDecks')}
            </button>
          </>
        }
      />
    </Frame>
  );
}
