import { useEffect } from 'react';
import type { LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { useNavigate } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { formatClock } from './useClock.js';
import styles from './Modes.module.css';

/** Where the close control and Escape lead: the screen the modes are picked on. */
export const MODES_HOME = '/decks';

interface ModeScreenProps {
  /** The mode's name, as the picker shows it. */
  title: string;
  /** What the mode asks, as the heading above the board. */
  ask?: string | undefined;
  /** Whether an answer here counts for the schedule, said once under the title. */
  counts: boolean;
  /** Progress through the run; absent while there is none (a timed round). */
  progress?: { done: number; total: number } | undefined;
  /** A clock: seconds left in a timed round, or seconds taken so far. */
  timer?: { seconds: number; label: string; low?: boolean } | undefined;
  /** What to read out after an answer (a live region). */
  said?: string;
  children: React.ReactNode;
  actions?: React.ReactNode;
}

/**
 * The frame every mode is drawn in. It owns the whole viewport like a
 * session, so nothing outside it can be pressed by accident, and Escape or
 * the close control goes back to the picker.
 */
export function ModeScreen({
  title,
  ask,
  counts,
  progress,
  timer,
  said = '',
  children,
  actions,
}: ModeScreenProps): React.JSX.Element {
  const navigate = useNavigate();
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape' && !event.defaultPrevented) void navigate(MODES_HOME);
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [navigate]);

  const share = progress === undefined || progress.total === 0 ? 0 : (progress.done / progress.total) * 100;
  return (
    <main className={styles.screen}>
      <div className={styles.topBar}>
        <button
          type="button"
          className={styles.close}
          aria-label={t('modes.leave')}
          onClick={() => {
            void navigate(MODES_HOME);
          }}
        >
          <Icon name="close" size={18} weight={2} />
        </button>
        {progress !== undefined ? (
          <>
            <div
              className={styles.track}
              role="progressbar"
              aria-valuenow={progress.done}
              aria-valuemin={0}
              aria-valuemax={progress.total}
              aria-label={t('modes.progress', { done: progress.done, total: progress.total })}
            >
              <div className={styles.fill} style={{ width: `${String(share)}%` }} />
            </div>
            <span className={styles.counter} aria-hidden="true">
              {progress.done}/{progress.total}
            </span>
          </>
        ) : (
          <div className={styles.track} aria-hidden="true" />
        )}
        {timer !== undefined && (
          <span
            className={cx(styles.clock, timer.low === true && styles.clockLow)}
            role="timer"
            aria-label={timer.label}
          >
            {formatClock(timer.seconds)}
          </span>
        )}
      </div>

      <div className={styles.head}>
        <div className={styles.kicker}>
          <span className={styles.chip}>{title}</span>
          <span>{counts ? t('modes.counts') : t('modes.practiceOnly')}</span>
        </div>
        {ask !== undefined && <h1 className={styles.ask}>{ask}</h1>}
      </div>

      <div className={styles.stage}>{children}</div>
      {actions !== undefined && <div className={styles.actions}>{actions}</div>}

      <p className="sr-only" role="status" aria-live="polite">
        {said}
      </p>
    </main>
  );
}

interface ModeSummaryProps {
  title: string;
  /** The notebook's target language, for the missed words. */
  lang: LanguageCode;
  /** The headline: a score, a time. */
  score: string;
  /** Extra lines under it. */
  lines?: string[];
  best?: 'new' | number | undefined;
  missed: readonly { wordId: string; headword: string }[];
  onAgain: () => void;
}

/** The end of a round: what happened, the words worth another look, and the way on. */
export function ModeSummary({
  title,
  lang,
  score,
  lines = [],
  best,
  missed,
  onAgain,
}: ModeSummaryProps): React.JSX.Element {
  const navigate = useNavigate();
  return (
    <main className={styles.screen}>
      <div className={styles.summary}>
        <div className={styles.summaryHead}>
          <span className={styles.summaryMark}>
            <Icon name="check" size={28} weight={2.2} />
          </span>
          <h1 className={styles.summaryTitle}>{t('modes.doneTitle')}</h1>
          <span className={styles.chip}>{title}</span>
          <span className={styles.score} role="status">
            {score}
          </span>
          {lines.map((line) => (
            <p key={line} className={styles.note}>
              {line}
            </p>
          ))}
          {best === 'new' && <span className={styles.best}>{t('modes.newBest')}</span>}
          {typeof best === 'number' && (
            <span className={styles.best}>{t('modes.best', { count: best })}</span>
          )}
        </div>
        {missed.length > 0 ? (
          <section className={styles.missed} aria-labelledby="mode-missed">
            <h2 id="mode-missed" className={styles.missedTitle}>
              {t('modes.worthALook')}
            </h2>
            <ul className={styles.missedList}>
              {missed.map((word) => (
                <li key={word.wordId} className={styles.missedWord}>
                  <Bilingual lang={lang}>{word.headword}</Bilingual>
                </li>
              ))}
            </ul>
          </section>
        ) : null}
      </div>
      <div className={styles.actions}>
        <button type="button" className={styles.primary} onClick={onAgain}>
          {t('modes.playAgain')}
        </button>
        <button
          type="button"
          className={styles.secondary}
          onClick={() => {
            void navigate(MODES_HOME);
          }}
        >
          {t('modes.backToDecks')}
        </button>
      </div>
    </main>
  );
}

/** The No timer switch: an accessibility choice, remembered on this device. */
export function NoTimer({
  on,
  onChange,
}: {
  on: boolean;
  onChange: (on: boolean) => void;
}): React.JSX.Element {
  return (
    <button
      type="button"
      className={styles.toggle}
      aria-pressed={on}
      onClick={() => {
        onChange(!on);
      }}
    >
      <span className={styles.toggleBox} aria-hidden="true">
        {on && <Icon name="check" size={12} weight={2.6} />}
      </span>
      {t('modes.noTimer')}
    </button>
  );
}
